Client component (checked state + onChange). Reusing the switch anatomy pattern that works well here: real `<input type="checkbox">` visually hidden via `sr-only`, track+thumb as sibling spans styled through Tailwind's `peer` variant — keeps native keyboard/form behavior while looking like a proper switch. The label text stacks above an optional description (only rendered if provided), and the whole row is clickable via the outer `<label>`:
<tool_call>
{"name": "write_file", "arguments": {"path": "components/LabeledSwitch.tsx", "content": ""use client";

type LabeledSwitchProps = {
  label: string;
  description?: string;
  checked: boolean;
  onChange: (value: boolean) => void;
};

export default function LabeledSwitch({ label, description, checked, onChange }: LabeledSwitchProps) {
  return (
    <label className="flex cursor-pointer items-start justify-between gap-4 py-3">
      <span className="space-y-0.5">
        <span className="block text-sm font-medium">{label}</span>
        {description ? (
          <span className="block text-sm text-zinc-500 dark:text-zinc-400">{description}</span>
        ) : null}
      </span>
      <span className="relative mt-0.5 inline-flex h-6 w-11 shrink-0 items-center">
        <input
          type="checkbox"
          checked={checked}
          onChange={(e) => onChange(e.target.checked)}
          className="peer sr-only"
        />
        <span
          aria-hidden="true"
          className="absolute inset-0 rounded-full bg-zinc-300 transition-colors duration-150 peer-checked:bg-zinc-900 peer-focus-visible:ring-2 peer-focus-visible:ring-zinc-500 peer-focus-visible:ring-offset-2 dark:bg-zinc-700 dark:peer-checked:bg-zinc-100 dark:peer-focus-visible:ring-offset-zinc-950"
        />
        <span
          aria-hidden="true"
          className="absolute left-0.5 h-5 w-5 rounded-full bg-white shadow transition-transform duration-150 peer-checked:translate-x-5 dark:bg-zinc-950 dark:peer-checked:bg-zinc-900"
        />
      </span>
    </label>
  );
}
"}}
</tool_call>

